type 'a qnode = { v : 'a; mutable next : 'a qnode option }
type 'a queue = { mutable head : 'a qnode option;
                  mutable tail : 'a qnode option }

   let dup_evens (q : int queue) : unit =
     let rec loop (qno : int qnode option) : unit =
       begin match qno with
       | None -> ()
       | Some qn ->
         if qn.v mod 2 = 0 then begin
           let copy = { v = qn.v; next = qn.next } in
           qn.next <- Some copy;
           loop copy.next
         end else loop qn.next
       end
     in loop q.head

