let tally () : widget * int value_controller =
  let vc = make_controller 0 in
  let count_w, count_lc = label "0" in
  let plus_w, _, plus_nc = button "+1" in
  let reset_w, _, reset_nc = button "Reset" in
  vc.add_change_listener (fun (v : int) -> count_lc.set_label (string_of_int v));
  plus_nc.add_event_listener
    (mouseclick_listener (fun () -> vc.change_value (vc.get_value () + 1)));
  reset_nc.add_event_listener (mouseclick_listener (fun () -> vc.change_value 0));
  (hlist [border count_w; border plus_w; border reset_w], vc)

public static int[] columnSums(int[][] grid) {
    int width = 0;
    for (int i = 0; i < grid.length; i++) {
        if (grid[i] != null && grid[i].length > width) {
            width = grid[i].length;
        }
    }
    int[] sums = new int[width];
    for (int i = 0; i < grid.length; i++) {
        if (grid[i] == null) {
            continue;
        }
        for (int j = 0; j < grid[i].length; j++) {
            sums[j] += grid[i][j];
        }
    }
    return sums;
}
